+
+    fn styled_pane_line(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        text: &str,
+        reversed: bool,
+    ) -> Spans<'static> {
+        let base_style = if reversed {
+            Style::default().add_modifier(Modifier::REVERSED)
+        } else {
+            Style::default()
+        };
+        let selected_range = self
+            .visual_selection
+            .as_ref()
+            .filter(|selection| selection.focus == pane)
+            .and_then(|selection| selection_range(selection, row, text.chars().count(), false));
+        styled_line(text, selected_range, base_style)
+    }
+
+    fn start_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let anchor = self.visual_anchor_position(right_content, right_cursor_column);
+        self.mode = UiMode::Command;
+        self.pending = None;
+        self.visual_selection = Some(VisualSelection {
+            focus: self.focus,
+            kind,
+            anchor,
+            cursor: anchor,
+        });
+    }
+
+    fn visual_anchor_position(
+        &self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> VisualPosition {
+        match self.focus {
+            PaneFocus::Left => VisualPosition {
+                row: self.control_selected,
+                column: 0,
+            },
+            PaneFocus::Right => self.right_visual_anchor_position(right_content, right_cursor_column),
+        }
+    }
+
+    fn right_visual_anchor_position(
+        &self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> VisualPosition {
+        let visible = self.visible_right_content(right_content);
+        let lines = visible.lines().collect::<Vec<_>>();
+        let row = lines.len().saturating_sub(1);
+        let line_len = lines
+            .last()
+            .map(|line| line.chars().count())
+            .unwrap_or_default();
+        VisualPosition {
+            row,
+            column: right_cursor_column.unwrap_or(line_len).min(line_len),
+        }
+    }
+
+    fn handle_visual_key(&mut self, key: UiKey) -> bool {
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+                true
+            }
+            UiKey::Char('v') => {
+                self.switch_visual_kind(VisualSelectionKind::Character);
+                true
+            }
+            UiKey::Char('V') => {
+                self.switch_visual_kind(VisualSelectionKind::Line);
+                true
+            }
+            UiKey::Char(ch) if ch == CTRL_V_CHAR => {
+                self.switch_visual_kind(VisualSelectionKind::Block);
+                true
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1);
+                true
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1);
+                true
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0);
+                true
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0);
+                true
+            }
+            _ => true,
+        }
+    }
+
+    fn switch_visual_kind(&mut self, kind: VisualSelectionKind) {
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.kind = kind;
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection.as_ref() else {
+            return;
+        };
+        let row_limit = self.visual_row_limit(selection.focus);
+        let column_limit = self.visual_column_limit(selection.focus);
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor.row = apply_delta(selection.cursor.row, row_delta, row_limit);
+            selection.cursor.column =
+                apply_delta(selection.cursor.column, column_delta, column_limit);
+        }
+    }
+
+    fn visual_row_limit(&self, focus: PaneFocus) -> usize {
+        match focus {
+            PaneFocus::Left => self.left_pane_display_lines().len().saturating_sub(1),
+            PaneFocus::Right => usize::from(self.right_inner_size().1.saturating_sub(1)),
+        }
+    }
+
+    fn visual_column_limit(&self, focus: PaneFocus) -> usize {
+        match focus {
+            PaneFocus::Left => usize::from(self.layout().left_width.saturating_sub(3)),
+            PaneFocus::Right => usize::from(self.right_inner_size().0.saturating_sub(1)),
+        }
+    }
+
+    fn visual_cursor_position(&self, selection: &VisualSelection) -> (u16, u16) {
+        let layout = self.layout();
+        match selection.focus {
+            PaneFocus::Left => (
+                selection.cursor.row.saturating_add(2).min(usize::from(u16::MAX)) as u16,
+                selection.cursor.column.saturating_add(2).min(usize::from(u16::MAX)) as u16,
+            ),
+            PaneFocus::Right => (
+                selection.cursor.row.saturating_add(2).min(usize::from(u16::MAX)) as u16,
+                layout
+                    .left_width
+                    .saturating_add(2)
+                    .saturating_add(
+                        selection
+                            .cursor
+                            .column
+                            .min(usize::from(u16::MAX)) as u16,
+                    ),
+            ),
+        }
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }

